"""Evaluate a palette corroboration gate on all 15 old consensus outputs.
This is a post-hoc development replay, not an independent control or full detector replay.
"""
import hashlib,json,copy
from pathlib import Path
import numpy as np
from app.tracking.teams import distinct_team_colors
from scripts.soccertrack_v2.benchmark_tracker_backends import groups

def load(p):return json.loads(Path(p).read_text())
def sha(p):
    with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def palette_support(before,after,centers):
    if len(before)!=3 or len(after)<3 or any(c is None for c in before+after):return False
    colors=np.asarray(before+after,dtype=float);centers=np.asarray(centers,dtype=float)
    if colors.shape!=(len(before+after),3) or not np.isfinite(colors).all() or not distinct_team_colors(centers):return False
    distances=np.linalg.norm(np.asarray([np.median(before,axis=0),np.median(after,axis=0)])[:,None]-centers,axis=2)
    if np.any(distances[:,0]==distances[:,1]):return False
    return bool(np.argmin(distances[0])!=np.argmin(distances[1]))

out=Path('.cache/consensus-palette-gate-development-v1');out.mkdir(exist_ok=False)
cases=[]
for group,spec in groups().items():
    for seg in spec['segments']:
        cases.append((group,seg,Path('.cache/consensus-production-v2')/group/f'seg_{seg:04d}.json',Path(spec['cache'])/f'seg_{seg:04d}.json'))
for group,segs in [('day',[60,62]),('night',[80,82])]:
    root=Path('data/tracking/bench/consensus_control_v1')/group
    for seg in segs:cases.append(('closed_'+group,seg,root/'predictions/consensus'/f'seg_{seg:04d}.json',root/'raw'/f'seg_{seg:04d}.json'))
paths=[Path(__file__),Path('app/tracking/teams.py')]+[p for _,_,a,b in cases for p in [a,b]]
hashes={str(p):sha(p) for p in paths};reports=[]
for group,seg,pred,raw_path in cases:
    original=load(pred);raw=load(raw_path);candidate=copy.deepcopy(original)
    bounds=original['summary']['calibration_stats']['identity_consensus']['boundaries']
    source={(s['order'],tuple(r['box'])):r['color'] for s in raw['samples'] for r in raw['detected_persons'][str(s['order'])]}
    reverse={b['new_id']:b['raw_id'] for b in bounds}
    obs={}
    for s in original['samples']:
        for p in s['persons']:
            tid=reverse.get(p[0],p[0]);obs.setdefault(tid,[]).append((s['order'],source[s['order'],tuple(p[1:5])]))
    choices=[];remap={};next_id=max((reverse.get(p[0],p[0]) for s in original['samples'] for p in s['persons']),default=0)+1
    current={}
    for b in bounds:
        items=obs[b['raw_id']];before=[c for order,c in items if order<b['first_order']][-3:]
        after=[c for order,c in items if b['first_order']<=order<=b['confirmed_order']]
        keep=palette_support(before,after,original['summary']['team_colors'])
        if keep:current[b['raw_id']]=next_id;next_id+=1
        remap[b['new_id']]=current.get(b['raw_id'],b['raw_id'])
        choices.append(dict(boundary=b,accepted=keep,before=before,after=after))
    for s in candidate['samples']:
        teams={}
        for p in s['persons']:
            old=p[0];p[0]=remap.get(old,old);teams[str(p[0])]=s['person_teams'].get(str(old))
        s['person_teams']=teams
    def evidence(payload):
        return [(s['order'],s['frame_idx'],s['seconds'],s['continuity_id'],s['ball'],s['ball_source'],
                 [(p[1:],s['person_teams'].get(str(p[0]))) for p in s['persons']]) for s in payload['samples']]
    assert evidence(original)==evidence(candidate)
    target=out/group/f'seg_{seg:04d}.json';target.parent.mkdir(parents=True,exist_ok=True)
    # Keep original summary explicitly under its historical name; it is not recomputed metrics.
    payload=dict(samples=candidate['samples'],original_summary=original['summary'],palette_choices=choices)
    target.write_text(json.dumps(payload)+'\n')
    reports.append(dict(group=group,segment=seg,choices=choices,output=str(target),output_sha256=sha(target),
       observations=sum(len(s['persons']) for s in original['samples']),source_and_team_evidence_exact=True))
    print(group,seg,[(r['boundary']['raw_id'],r['accepted']) for r in choices],flush=True)
assert hashes=={p:sha(p) for p in hashes}
(out/'report.json').write_text(json.dumps(dict(scope=__doc__,hashes=hashes,reports=reports,
    note='Gate uses existing RGB palette and exactly existing three-observation windows, no threshold search. Colors are not person GT. No new control or production change.'),indent=2))
